    }finally{$db->execute_query("UPDATE usuario_unidad_permisos SET nivel='editar' WHERE usuario_id=? AND unidad_id=? AND modulo='inventario'",[$operadorId,$restaurante]);}
    $reader->login($f['cuentas']['lectura_restaurante']);$readOnly=$reader->request('GET',$article);$a($readOnly['status']===200&&str_contains($readOnly['body'],'Solo consulta')&&!str_contains($readOnly['body'],'>Guardar uso<')&&!str_contains($readOnly['body'],'data-admin-modal-open="almacen-asociar"')&&ClienteInstalacion3E::dom($readOnly['body'])->query('//a[contains(@href,"asociar=")]')->length===0,'Solo lectura consulta la ficha sin acciones de escritura.');
    $antes=$conf($id);$r=$reader->request('POST',$article,['tipo'=>'preparacion']+ClienteInstalacion3E::form($readOnly['body'],'clasificar'));$a(in_array($r['status'],[403,303],true)&&$conf($id)===$antes,'Solo lectura no guarda el uso por POST.');
    $listaLectura=$reader->request('GET','/admin/recetas/articulos');$a($listaLectura['status']===200&&!str_contains($listaLectura['body'],'data-m6-abrir-alta')&&!str_contains($listaLectura['body'],'data-m6-alta'),'Solo lectura no recibe el diálogo de alta.');$noCreate=$reader->request('GET','/admin/almacenes/catalogo/nuevo');$a($noCreate['status']===403,'Lectura de Almacenes no concede crear identidades.');

    echo json_encode(['ok'=>true,'comprobaciones'=>$n,'resultados'=>$checks,'articulo'=>$id],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
